from epja_avis_d_common import K, O15

# ====================================================== OAD-15 clase 1
F = ("Ficha 1 (proyecto ficticio «Miradas de Invierno» en una biblioteca de barrio). Equipo de 6 personas con estos roles: R1 coordinación, R2 montaje, R3 difusión, R4 finanzas, R5 atención de público, R6 registro. "
     "Cronograma, contando los días desde el día 1: T1 seleccionar obras, días 1 a 3. T2 imprimir carteles y fichas de obra, días 4 a 5. T3 difundir en el panel y en el grupo del barrio, días 6 a 12. "
     "T4 montaje en el muro, días 13 a 14. T5 muestra abierta, días 15 y 16. T6 desmontaje y cierre, día 17.")
